/* Social workspace UI. All accounts, metrics and assistant responses are illustrative. */
const socialIcons={instagram:'<rect x="4" y="4" width="16" height="16" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17" cy="7" r=".7" fill="currentColor"/>',telegram:'<path d="m3 10 18-7-4 18-6-6-4 3v-5l10-7-8 9z"/>',whatsapp:'<path d="M4 17a9 9 0 1 1 4 3l-6 2z"/><path d="M8 7c0 5 4 9 9 9l1-3-3-1-1 1-3-3 1-1-1-3z"/>',linkedin:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M7 10v7m0-10v.2m4 10v-7m0 3c0-4 6-4 6 0v4"/>',youtube:'<rect x="2" y="5" width="20" height="14" rx="5"/><path d="m10 9 5 3-5 3z"/>',facebook:'<path d="M14 22V13h3l1-4h-4V7c0-2 1-2 4-2V1h-4c-4 0-5 3-5 6v2H6v4h3v9"/>'};
function social(n){return `<span class="social ${n}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${socialIcons[n]||socialIcons.instagram}</svg></span>`}
const socialNames={instagram:'اینستاگرام',telegram:'تلگرام',whatsapp:'واتس‌اپ',linkedin:'لینکدین',youtube:'یوتیوب',facebook:'فیسبوک'};
function readLocal(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
let accounts=readLocal('ht-accounts',[{id:'ig-demo',network:'instagram',name:'hashtiva.studio'},{id:'tg-demo',network:'telegram',name:'Hashtiva community'},{id:'wa-demo',network:'whatsapp',name:'Hashtiva business'}]);let scope='all';let view='grid';let ideasSaved=readLocal('ht-ideas',[]);let taskChecks=readLocal('ht-tasks',[]);let agentMessages=[];let scheduleOffset=0;
const contexts={dashboard:['نبض رشد کسب‌وکار','اولویت‌های امروز من چیست؟','یک برنامه ساده: ابتدا پیام‌های بی‌پاسخ را بررسی کنید، سپس یک محتوای آموزشی کوتاه آماده کنید و در پایان نتیجه انتشار قبلی را مقایسه کنید.'],studio:['همکار خلاق شما','برای محتوای بعدی ایده بده','ایده پیشنهادی: «۳ اشتباه رایج در شروع کار». با یک سؤال شروع کنید، برای هر اشتباه یک راه‌حل کوتاه نشان دهید و در پایان از مخاطب بخواهید تجربه‌اش را بنویسد.'],inbox:['دستیار گفتگو','یک پاسخ دوستانه پیشنهاد بده','پاسخ پیشنهادی: «سلام، خوش اومدید! خوشحال می‌شیم راهنمایی‌تون کنیم. می‌گید بیشتر دنبال چه خدمتی هستید تا مناسب‌ترین گزینه رو معرفی کنیم؟» پیش از ارسال، پاسخ را با سؤال مخاطب تطبیق دهید.'],analytics:['تحلیل‌گر رشد','کدام معیار را بهتر کنم؟','علاوه بر بازدید، نسبت ذخیره و اشتراک‌گذاری به دسترسی را بررسی کنید. دو محتوای هم‌موضوع با شروع‌های متفاوت منتشر کنید و پس از یک بازه برابر نتایج را مقایسه کنید.'],automations:['معمار جریان‌های هوشمند','یک سناریوی خودکار پیشنهاد بده','سناریو: دریافت کلمه «راهنما» ← ارسال پیام معرفی ← پرسیدن نیاز مخاطب ← ارجاع به تیم در صورت سؤال تخصصی. برای پیام‌های تکراری فاصله زمانی بگذارید.'],audience:['همراه شناخت مخاطب','مخاطبان را چطور دسته‌بندی کنم؟','سه گروه ابتدایی بسازید: مخاطب تازه، علاقه‌مند فعال و مشتری. برای هر گروه یک هدف ارتباطی مشخص انتخاب کنید و از ارسال پیام یکسان به همه پرهیز کنید.'],channels:['هماهنگ‌کننده شبکه‌ها','برای هر شبکه چه محتوایی بسازم؟','یک موضوع را به چند قالب تبدیل کنید: ریلز کوتاه برای اینستاگرام، توضیح عمیق‌تر برای تلگرام، و پیام کاربردی کوتاه برای مخاطبان رضایت‌داده در واتس‌اپ.'],growth:['استراتژیست برند','یک آزمایش رشد پیشنهاد بده','یک هفته روی یک فرضیه تمرکز کنید: «شروع با یک سؤال، گفتگو را بیشتر می‌کند». دو محتوای مشابه آماده کنید، تنها شروع را تغییر دهید و تعداد گفتگو به ازای دسترسی را مقایسه کنید.'],calendar:['برنامه‌ریز محتوا','برنامه هفتگی بچین','یک ترکیب پیشنهادی: شنبه آموزش، دوشنبه پشت صحنه، چهارشنبه پاسخ به سؤال مخاطب و جمعه مرور هفته. تعداد انتشار را متناسب با توان تیم تنظیم کنید.'],settings:['نگهبان صدای برند','لحن برندم را چطور تعریف کنم؟','سه ویژگی برای لحن انتخاب کنید؛ مثلاً صمیمی، روشن و قابل اعتماد. یک نمونه متن مطلوب و چند عبارت ممنوع ثبت کنید تا تیم در تمام شبکه‌ها یک‌دست بنویسد.']};
const aiOrb=()=>`<span class="ai-orb" aria-hidden="true">${octopusIcon()}</span>`;
function art(type=0){return `<div class="content-art art-${type%4}"><span class="art-kicker">HASHTIVA / CREATIVE STUDIO</span><i class="art-circle"></i><i class="art-wire"></i><div class="art-copy">${['ایده‌های بزرگ<br>از همین‌جا<br><em>شروع می‌شن.</em>','کمتر اسکرول کن.<br><em>بیشتر الهام بگیر.</em>','پشت هر برند،<br>یک <em>داستان</em><br>منتظر شنیدنه.','یک ارتباط تازه.<br>یک <em>فرصت تازه.</em>'][type%4]}</div><span class="art-star">✳</span><span class="art-tag">${['CREATE SOMETHING GREAT','MAKE IT SOCIAL','TELL YOUR STORY','CONNECT & GROW'][type%4]}</span></div>`}
const originalDashboard=dashboard,originalRender=render;
pages.push(['channels','شبکه‌های اجتماعی','flow'],['calendar','تقویم انتشار','calendar'],['growth','آزمایشگاه رشد','chart']);
nav.innerHTML=`<div class="nav-group-label">مدیریت و انتشار</div>${pages.filter(p=>!['growth','channels'].includes(p[0])).map(([id,label,ic])=>`<button class="nav-item" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='inbox'?'<span class="badge">۱۲</span>':''}</button>`).join('')}<div class="nav-group-label">هوش و ارتباطات</div>${[['growth','آزمایشگاه رشد','chart'],['channels','شبکه‌های اجتماعی','flow']].map(([id,label,ic])=>`<button class="nav-item" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='growth'?'<span class="ai-mini"><img class="octopus-inline" src="assets/octopus.svg" alt="هوش مصنوعی"></span>':''}</button>`).join('')}`;
document.querySelector('.upgrade').innerHTML=`${aiOrb()}<b>تیم کوچک، ایده‌های بزرگ</b><p>یک دستیار برای تمام مسیر رشد شما.</p><button data-agent="start">با دستیار گفتگو کنید ↖</button>`;
document.querySelector('#notifications').innerHTML=icon('inbox')+'<i></i>';
function copilotStrip(){const c=contexts[current]||contexts.settings;return `<section class="copilot-strip"><div class="copilot-title">${aiOrb()}<div><b>${c[0]}</b><small>پیشنهادهای آمادهٔ هشتیوا · پیش‌نمایش AI</small></div></div><p>${c[2].split(' .')[0].slice(0,105)}…</p><button class="btn ai-button" data-agent="context">${c[1]} ↖</button></section>`}
function networkRail(){return `<section class="network-rail"><div><small>فضای اجتماعی شما</small><b>${accounts.length.toLocaleString('fa-IR')} حساب نمونه، یک نمای مشترک</b></div><div class="network-pills"><button class="network-pill ${scope==='all'?'picked':''}" data-scope="all">همه شبکه‌ها</button>${accounts.map(a=>`<button class="network-pill ${scope===a.id?'picked':''}" data-scope="${safe(a.id)}">${social(a.network)}<span>${safe(a.name)}</span><i></i></button>`).join('')}<button class="add-network" data-add-account aria-label="افزودن حساب">+</button></div></section>`}
function visualDashboard(){let html=originalDashboard();const start=html.indexOf('<section class="hero">'),end=html.indexOf('<div class="section-label">');html=html.slice(0,start)+networkRail()+`<section class="hero social-hero"><div class="hero-message"><span class="eyebrow"><span class="live-dot"></span> YOUR SOCIAL GROWTH PARTNER</span><h2>هر ایده، یک گفتگو.<br>هر گفتگو، یک فرصت <em>رشد.</em></h2><p>از اولین جرقه تا ارتباط با مخاطب؛<br>همه شبکه‌ها و ایده‌های شما، در یک فضای هوشمند.</p><div class="hero-actions"><button class="btn primary" data-page="growth">${icon('plus')} ایده بعدی‌ام را پیدا کن</button><button class="hero-link" data-page="calendar">برنامه این هفته ←</button></div><span class="hero-caption">برنامه‌ریزی کنید. گفتگو بسازید. رشد کنید.</span></div><div class="social-universe" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="universe-center">${aiOrb()}<span>YOUR AI COPILOT</span></div><span class="float-social float-ig">${social('instagram')}</span><span class="float-social float-tg">${social('telegram')}</span><span class="float-social float-wa">${social('whatsapp')}</span><span class="float-social float-yt">${social('youtube')}</span><div class="floating-insight"><img class="octopus-inline" src="assets/octopus.svg" alt=""> ایده بعدی شما آماده است<span>از ایده تا محتوای اثرگذار</span></div><div class="floating-growth">↗<b>با هم، رو به رشد</b><svg viewBox="0 0 100 32"><path d="m2 27 17-4 10 2 18-14 13 5 15-12 22-3" fill="none" stroke="#14B8A6" stroke-width="3"/></svg></div></div></section>`+html.slice(end);return html+`<div class="section-label"><h2>جرقه‌های خلاقانه برای برند شما</h2><button class="text-link" data-page="growth">رفتن به آزمایشگاه رشد ←</button></div><div class="creative-grid">${[0,1,2].map((i)=>`<article class="creative-card">${art(i)}<div><small>ایده آماده · قابل ویرایش</small><h3>${['سه نکته که مخاطب شما نمی‌داند','یک روز از پشت صحنه برند','از یک سؤال، یک ریلز بساز'][i]}</h3><button class="text-link" data-use-idea="${i}">تبدیل به پیش‌نویس ←</button></div></article>`).join('')}</div>`}
function studioV2(){return heading('ایده‌ها اینجا جان می‌گیرند.','خلق، بازبینی و انتشار؛ یک استودیو برای همه شبکه‌های شما.')+`<div class="workspace-toolbar"><div class="filter-tabs"><button class="${view==='grid'?'selected':''}" data-view="grid">نمای گالری</button><button class="${view==='list'?'selected':''}" data-view="list">فهرست محتوا</button></div><button class="btn" data-page="calendar">${icon('calendar')} تقویم انتشار</button><span class="muted">${posts.length.toLocaleString('fa-IR')} محتوا در فضای نمایشی</span></div>${view==='list'?`<div class="card">${postRows()}</div>`:`<div class="creative-grid">${posts.map((p,i)=>`<article class="creative-card">${art(i)}<div><div class="content-meta">${social(p.network||'instagram')}<span class="status ${p.draft?'draft':''}">${p.draft?'پیش‌نویس':'زمان‌بندی‌شده'}</span></div><h3>${safe(p.title)}</h3><p>${safe(p.kind)} · ${safe(p.time)}</p><button class="text-link" data-edit-post="${i}">بازبینی محتوا ↖</button></div></article>`).join('')}<button class="new-content-tile" data-action="post"><span>+</span><b>داستان بعدی شما چیست؟</b><small>یک محتوای تازه خلق کنید</small></button></div>`}`}
function channelsPage(){return heading('تمام شبکه‌ها، کنار هم.','حساب‌های اجتماعی برندتان را در یک فضای مشترک مدیریت کنید.',false)+`<div class="page-banner"><div><b>برند شما، فراتر از یک شبکه</b><p>برای هر حساب، یک فضای انتشار و گفتگو. حساب‌های این پیش‌نمایش واقعی نیستند.</p></div><button class="btn primary" data-add-account>+ افزودن حساب نمونه</button></div><div class="channels-grid">${Object.keys(socialNames).map(n=>{let ac=accounts.filter(a=>a.network===n);return `<article class="card channel-card"><div class="card-title">${social(n)}<span class="network-type">${ac.length?ac.length.toLocaleString('fa-IR')+' حساب نمونه':'آماده افزودن نمونه'}</span></div><h3>${socialNames[n]}</h3><p>${{instagram:'ریلز، استوری و ارتباط با جامعه مخاطبان',telegram:'محتوای عمیق و جامعه‌ای همیشه همراه',whatsapp:'گفتگوی نزدیک‌تر با مشتریان کسب‌وکار',linkedin:'صدای حرفه‌ای برند شما',youtube:'داستان‌هایی که ارزش تماشا دارند',facebook:'ارتباط با جامعه و صفحه کسب‌وکار'}[n]}</p><div class="account-list">${ac.map(a=>`<div><span dir="auto">${safe(a.name)}</span><button data-remove-account="${safe(a.id)}" aria-label="حذف حساب نمونه ${safe(a.name)}">×</button></div>`).join('')}</div><button class="btn" data-add-network="${n}">+ افزودن ${ac.length?'حساب دیگر':'حساب نمونه'}</button></article>`}).join('')}</div><div class="connection-note">ⓘ در این نسخه هیچ ورود، دریافت رمز یا اتصال به سرویس خارجی انجام نمی‌شود. اضافه‌کردن حساب، فقط ساخت یک نمونه محلی است.</div>`}
const growthIdeas=[['آموزش کوتاه','۳ اشتباه رایج که می‌توان از آن‌ها پیشگیری کرد','یک ریلز ۳۰ ثانیه‌ای با شروع سؤال‌محور بسازید؛ هر اشتباه را با یک راه‌حل نشان دهید.','ذخیره و اشتراک‌گذاری'],['اعتمادسازی','آدم‌های پشت برند را نشان بده','یک روایت کوتاه از روز کاری تیم با یک چالش واقعی و راه‌حل آن منتشر کنید.','گفتگو و اعتماد'],['تعامل','این بار انتخاب را به مخاطب بسپار','دو گزینه مرتبط با محصول یا محتوای بعدی را در استوری بگذارید و نتیجه را فردا منتشر کنید.','پاسخ و مشارکت'],['توزیع محتوا','یک ایده، سه روایت متفاوت','موضوع موفق قبلی را به ریلز، یادداشت تلگرام و پیام کوتاه واتس‌اپ تبدیل کنید.','دسترسی هدفمند']];
function growthPage(){return heading('آزمایشگاه رشد','ایده را به آزمایش تبدیل کنید؛ نتیجه را بسنجید و قدم بعدی را پیدا کنید.',false)+`<div class="growth-intro">${aiOrb()}<div><span class="eyebrow">HASHTIVA INTELLIGENCE</span><h2>بهترین ایده بعدی شما، از شناخت مخاطب شروع می‌شود.</h2><p>پیشنهادهای آماده برای الهام؛ این نسخه داده واقعی صفحه را تحلیل نمی‌کند.</p></div><button class="btn ai-button" data-agent="context">برنامه رشد من ↖</button></div><div class="workspace-toolbar"><b>بانک ایده‌های رشد</b><span class="muted">${ideasSaved.length.toLocaleString('fa-IR')} ایده ذخیره‌شده</span></div><div class="growth-grid">${growthIdeas.map((g,i)=>`<article class="card idea-card"><div class="card-title"><span class="idea-number">0${i+1}</span><span class="idea-category">${g[0]}</span></div><h3>${g[1]}</h3><p>${g[2]}</p><small>هدف آزمایش: ${g[3]}</small><div class="idea-actions"><button class="btn primary" data-use-idea="${i}">ساخت پیش‌نویس</button><button class="btn" data-save-idea="${i}">${ideasSaved.includes(i)?'✓ ذخیره‌شده':'ذخیره ایده'}</button></div></article>`).join('')}</div><div class="card experiment"><div><h2>آزمایش ۷ روزه: شروع متفاوت، نتیجه متفاوت</h2><p>دو محتوای هم‌موضوع بسازید و فقط جمله آغازین را تغییر دهید.</p></div>${['انتخاب موضوع مشترک','ساخت دو شروع متفاوت','انتشار در شرایط مشابه','مقایسه نرخ تعامل'].map((t,i)=>`<label class="check-task"><input type="checkbox" data-task="${i}" ${taskChecks.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}<small>پیشرفت شما در همین مرورگر ذخیره می‌شود.</small></div>`}
function calendarPage(){let base=new Date();base.setDate(base.getDate()+scheduleOffset*7);const dates=Array.from({length:7},(_,i)=>{let d=new Date(base);d.setDate(d.getDate()+i);return d});return heading('ریتم انتشار برند شما','یک نگاه به هفته پیش رو؛ ایده‌ها را به برنامه تبدیل کنید.')+`<div class="workspace-toolbar"><button class="btn" data-week="-1">→ هفته قبل</button><b>${new Intl.DateTimeFormat('fa-IR',{month:'long',year:'numeric'}).format(base)}</b><button class="btn" data-week="1">هفته بعد ←</button><button class="text-link" data-week="0">امروز</button></div><div class="calendar-grid">${dates.map((d,i)=>`<section class="day-column"><div class="day-title"><small>${new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d)}</small><b>${new Intl.DateTimeFormat('fa-IR',{day:'numeric'}).format(d)}</b></div>${scheduleOffset===0&&i<posts.length?`<button class="calendar-post" data-edit-post="${i}">${social(posts[i].network||'instagram')}<b>${safe(posts[i].title)}</b><small>${safe(posts[i].time)}</small><span>${posts[i].draft?'پیش‌نویس':'نمونه برنامه‌ریزی'}</span></button>`:'<span class="day-empty">فضا برای یک ایده تازه</span>'}<button class="day-add" data-action="post" aria-label="ساخت محتوا">+</button></section>`).join('')}</div><p class="connection-note">این تقویم یک چیدمان هفتگی نمونه است؛ زمان‌بندی واقعی انتشار انجام نمی‌شود.</p>`}
function analyticsExtra(){return `<div class="section-label"><h2>هر شبکه، یک فرصت متفاوت</h2><small>مقایسه نمونه · بدون اتصال به آمار واقعی</small></div><div class="channels-grid">${accounts.map((a,i)=>`<div class="card channel-metric"><div class="card-title">${social(a.network)}<b dir="auto">${safe(a.name)}</b></div><div class="metric-bars">${[35,59,42,73,62,86,95].map((v,j)=>`<i style="height:${Math.max(15,v-i*8)}%;opacity:${.35+j*.09}"></i>`).join('')}</div><small>${socialNames[a.network]} · روند فعالیت نمونه</small></div>`).join('')}</div>`}
function settingsExtra(){return `<section class="card brand-settings"><div class="card-title"><h2>هویت برند و صدای تیم</h2><span class="ai-mini">AI CONTEXT</span></div><form id="brand-form"><label>لحن برند</label><select name="tone"><option>صمیمی و حرفه‌ای</option><option>رسمی و دقیق</option><option>جسور و خلاق</option></select><label>مخاطب اصلی برند</label><input name="target" placeholder="مثلاً صاحبان کسب‌وکارهای کوچک" value="${safe(localStorage.getItem('ht-target')||'')}"><label>موضوعات محتوایی</label><input name="topics" placeholder="آموزش، پشت صحنه، تجربه مشتری" value="${safe(localStorage.getItem('ht-topics')||'')}"><p><button class="btn primary">ذخیره پروفایل برند</button></p></form></section><section class="card brand-settings"><h2>اعضای فضای کار</h2><div class="schedule-row"><span class="avatar">م</span><div><b>مدیر کسب‌وکار</b><small>مالک فضای نمایشی</small></div><span class="status">دسترسی کامل</span></div><small>دعوت و مدیریت دسترسی واقعی در این پیش‌نمایش فعال نیست.</small></section>`}
render=function(page='dashboard'){if(!pages.some(p=>p[0]===page)&&!['settings','help','plans'].includes(page))page='dashboard';originalRender(page);if(page==='dashboard')main.innerHTML=visualDashboard();if(page==='studio')main.innerHTML=studioV2();if(page==='channels')main.innerHTML=channelsPage();if(page==='growth')main.innerHTML=growthPage();if(page==='calendar')main.innerHTML=calendarPage();if(page==='analytics')main.insertAdjacentHTML('beforeend',analyticsExtra());if(page==='settings'){main.insertAdjacentHTML('beforeend',settingsExtra());const tone=main.querySelector('[name="tone"]');if(localStorage.getItem('ht-tone'))tone.value=localStorage.getItem('ht-tone')}if(page==='inbox'){main.insertAdjacentHTML('afterbegin',`<div class="inbox-network-line"><b>صندوق مشترک شبکه‌ها</b>${['instagram','telegram','whatsapp'].map((n,i)=>`<button class="network-pill ${chat===i?'picked':''}" data-chat="${i}">${social(n)}${socialNames[n]}</button>`).join('')}<small>گفتگوهای نمونه</small></div>`)}if(page==='automations')main.insertAdjacentHTML('afterbegin',`<div class="workflow-banner"><span class="workflow-node">${social('instagram')} دریافت پیام</span><i>←</i><span class="workflow-node">${aiOrb()} تشخیص درخواست</span><i>←</i><span class="workflow-node">${social('whatsapp')} پیشنهاد پاسخ</span><small>پیش‌نمایش مسیر عامل هوشمند</small></div>`);main.insertAdjacentHTML('beforeend',copilotStrip());document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));updateAgentHeader();let acc=document.querySelector('#account');if(acc)acc.innerHTML=`${social('instagram')}<span>حساب‌ها و شبکه‌ها</span> ⌄`;};
function accountModal(network='instagram'){modal(`<h2>فضای اجتماعی‌تان را گسترش دهید</h2><small>افزودن حساب نمونه؛ بدون ورود یا اتصال واقعی</small><form id="account-form"><label>شبکه اجتماعی</label><select name="network">${Object.entries(socialNames).map(([k,n])=>`<option value="${k}" ${k===network?'selected':''}>${n}</option>`).join('')}</select><label>نام حساب</label><input name="name" placeholder="نام برند یا شناسه صفحه" required maxlength="50"><p class="connection-note">این نام فقط در مرورگر شما ذخیره می‌شود. رمز عبور یا توکن وارد نکنید.</p><button class="btn primary">افزودن حساب نمونه</button></form>`)}
function editPost(i){const p=posts[i];modal(`<h2>بازبینی محتوا</h2><form id="edit-post-form" data-index="${i}"><label>عنوان</label><input name="title" value="${safe(p.title)}" required maxlength="90"><label>شبکه انتشار</label><select name="network">${Object.entries(socialNames).map(([n,label])=>`<option value="${n}" ${(p.network||'instagram')===n?'selected':''}>${label}</option>`).join('')}</select><label>متن و ایده</label><textarea name="caption">${safe(p.caption||'')}</textarea><p><button type="button" class="btn ai-button" data-agent="caption"><img class="octopus-inline" src="assets/octopus.svg" alt=""> پیشنهاد متن</button></p><label>وضعیت</label><select name="draft"><option value="yes" ${p.draft?'selected':''}>پیش‌نویس</option><option value="no" ${!p.draft?'selected':''}>آماده بازبینی</option></select><p><button class="btn primary">ذخیره تغییرات</button></p><small>این محتوا فقط در فضای نمایشی همین مرورگر نگهداری می‌شود.</small></form>`)}
const persistedPosts=readLocal('ht-posts',null);if(Array.isArray(persistedPosts)&&persistedPosts.length)posts=persistedPosts;
function persistPosts(){localStorage.setItem('ht-posts',JSON.stringify(posts))}
// Persistent assistant surface, separate from route content.
document.body.insertAdjacentHTML('beforeend',`<button id="agent-launcher" aria-label="گفتگو با دستیار هشتیوا" aria-expanded="false">${aiOrb()}<span>از هشتیوا بپرس<small>همراه ایده‌های شما</small></span><i><img class="octopus-inline" src="assets/octopus.svg" alt=""></i></button><section id="agent-panel" aria-label="دستیار هشتیوا" hidden><div class="agent-header">${aiOrb()}<div><b>هشتیوا، همکار هوشمند شما</b><small id="agent-context"></small></div><button id="agent-close" aria-label="بستن دستیار">×</button></div><div class="agent-demo-label">پیش‌نمایش تعاملی · پاسخ‌های آماده، بدون مدل زنده</div><div id="agent-messages" aria-live="polite"></div><div id="agent-prompts"></div><form id="agent-form"><input name="question" aria-label="سؤال از دستیار" placeholder="درباره رشد و محتوا بپرسید…" required autocomplete="off"><button aria-label="ثبت سؤال">↑</button></form></section>`);
function updateAgentHeader(){const c=contexts[current]||contexts.settings;document.querySelector('#agent-context').textContent=c[0];document.querySelector('#agent-prompts').innerHTML=`<button data-agent-question="context">${c[1]}</button><button data-agent-question="content">ایده محتوا</button><button data-agent-question="growth">برنامه رشد</button>`}
function agentRender(){document.querySelector('#agent-messages').innerHTML=agentMessages.length?agentMessages.map(m=>`<div class="agent-message ${m.role}">${m.role==='assistant'?'<span class="ai-message-label"><img class="octopus-inline" src="assets/octopus.svg" alt=""> پیشنهاد هشتیوا</span>':''}${safe(m.text)}</div>`).join(''):`<div class="agent-welcome">${aiOrb()}<h3>با هم، ایده را جلو ببریم.</h3><p>برای هر بخش یک پیشنهاد کاربردی دارم. از سؤال‌های زیر شروع کنید.</p></div>`;const el=document.querySelector('#agent-messages');el.scrollTop=el.scrollHeight}
function openAgent(){if(dialog.open)dialog.close();document.querySelector('#agent-panel').hidden=false;document.querySelector('#agent-launcher').setAttribute('aria-expanded','true');updateAgentHeader();agentRender();document.querySelector('#agent-form input').focus()}
function answerAgent(q,kind){agentMessages.push({role:'user',text:q});let c=contexts[current]||contexts.settings;let answer=c[2];if(kind==='content'||/کپشن|محتوا|ایده|ریلز/.test(q))answer=contexts.studio[2];else if(kind==='growth'||/رشد|استراتژی|برنامه/.test(q))answer=contexts.growth[2];else if(/پیام|پاسخ|مشتری/.test(q))answer=contexts.inbox[2];else if(/تلگرام|واتس|شبکه/.test(q))answer=contexts.channels[2];else if(kind!=='context')answer='این پیش‌نمایش پاسخ آزاد تولید نمی‌کند. پیشنهاد مرتبط با بخش فعلی: '+answer;agentMessages.push({role:'assistant',text:answer});agentRender()}
document.querySelector('#agent-launcher').onclick=()=>{const p=document.querySelector('#agent-panel');if(p.hidden)openAgent();else{p.hidden=true;document.querySelector('#agent-launcher').setAttribute('aria-expanded','false')}};document.querySelector('#agent-close').onclick=()=>{document.querySelector('#agent-panel').hidden=true;document.querySelector('#agent-launcher').setAttribute('aria-expanded','false');document.querySelector('#agent-launcher').focus()};
document.addEventListener('click',e=>{let t=e.target.closest('[data-add-account],[data-add-network]');if(t)accountModal(t.dataset.addNetwork);t=e.target.closest('[data-remove-account]');if(t){accounts=accounts.filter(a=>a.id!==t.dataset.removeAccount);localStorage.setItem('ht-accounts',JSON.stringify(accounts));render('channels');toast('حساب نمونه حذف شد')}t=e.target.closest('[data-scope]');if(t){scope=t.dataset.scope;if(scope!=='all'){const a=accounts.find(a=>a.id===scope);modal(`<h2>${socialNames[a.network]}</h2><p dir="auto">${safe(a.name)}</p><p>این حساب نمونه است و آمار اختصاصی ندارد. نمای داشبورد، داده‌های نمونه مشترک را نمایش می‌دهد.</p><button class="btn primary" data-page="channels">مدیریت حساب‌ها</button>`)}else render('dashboard')}t=e.target.closest('[data-view]');if(t){view=t.dataset.view;render('studio')}t=e.target.closest('[data-edit-post]');if(t)editPost(+t.dataset.editPost);t=e.target.closest('[data-use-idea]');if(t){const g=growthIdeas[+t.dataset.useIdea];posts.unshift({title:g[1],kind:'پست تصویری',time:'بدون زمان',draft:true,caption:g[2],network:'instagram'});persistPosts();location.hash='studio';render('studio');toast('ایده به پیش‌نویس تبدیل شد؛ برای ویرایش بازبینی را بزنید')}t=e.target.closest('[data-save-idea]');if(t){const i=+t.dataset.saveIdea;ideasSaved=ideasSaved.includes(i)?ideasSaved.filter(x=>x!==i):[...ideasSaved,i];localStorage.setItem('ht-ideas',JSON.stringify(ideasSaved));render('growth')}t=e.target.closest('[data-week]');if(t){scheduleOffset=+t.dataset.week===0?0:scheduleOffset+(+t.dataset.week);render('calendar')}t=e.target.closest('[data-agent]');if(t){openAgent();if(t.dataset.agent!=='start')answerAgent(t.dataset.agent==='caption'?'برای محتوا کپشن پیشنهاد بده':(contexts[current]||contexts.settings)[1],t.dataset.agent==='caption'?'content':'context')}t=e.target.closest('[data-agent-question]');if(t)answerAgent(t.textContent,t.dataset.agentQuestion);if(e.target.closest('[data-page]')&&dialog.open)dialog.close();if(e.target.closest('#account'))accountModal();if(e.target.closest('[data-action="post"]')){const form=document.querySelector('#post-form');form.insertAdjacentHTML('afterbegin',`<label>شبکه انتشار</label><select name="network">${Object.entries(socialNames).map(([n,label])=>`<option value="${n}">${label}</option>`).join('')}</select>`)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-task]')){const i=+e.target.dataset.task;taskChecks=e.target.checked?[...new Set([...taskChecks,i])]:taskChecks.filter(x=>x!==i);localStorage.setItem('ht-tasks',JSON.stringify(taskChecks))}});
document.addEventListener('submit',e=>{const f=new FormData(e.target);if(e.target.id==='account-form'){accounts.push({id:'local-'+Date.now(),network:f.get('network'),name:f.get('name').trim()||'حساب نمونه'});localStorage.setItem('ht-accounts',JSON.stringify(accounts));dialog.close();location.hash='channels';render('channels');toast('حساب نمونه اضافه شد؛ اتصال خارجی انجام نشد')}if(e.target.id==='edit-post-form'){let p=posts[+e.target.dataset.index];p.title=f.get('title');p.network=f.get('network');p.caption=f.get('caption');p.draft=f.get('draft')==='yes';if(!p.draft)p.time='منتظر تأیید';persistPosts();dialog.close();render(current);toast('تغییرات ذخیره شد')}if(e.target.id==='post-form'){posts[0].network=f.get('network');posts[0].caption=f.get('caption');persistPosts();render('studio')}if(e.target.id==='brand-form'){['tone','target','topics'].forEach(k=>localStorage.setItem('ht-'+k,f.get(k)));toast('پروفایل برند در مرورگر ذخیره شد')}if(e.target.id==='agent-form'){const q=f.get('question').trim();if(q){answerAgent(q);e.target.reset()}}});
render(location.hash.slice(1)||'dashboard');agentRender();
